jobset:
# container of each pod (template; __NAME__ is the JobSet's name)
command: ["sh", "-c"]
              args:
              - >-
                export LA_TASK_TS=$(date +%s.%N) LA_OUT=/shared/la/runs/$RUN;
                mkdir -p $LA_OUT;
                (date +%s.%N; getent hosts __MASTER__; cat /etc/resolv.conf) > $LA_OUT/dns_$JOB_COMPLETION_INDEX.txt 2>&1;
                if [ "$JOB_COMPLETION_INDEX" = 1 ]; then __POD1__ true; fi;
                exec python /shared/la/la_torchrun.py --nnodes=2 --nproc-per-node=2 --node-rank=$JOB_COMPLETION_INDEX
                --master-addr=__MASTER__ --master-port=29500 __RDZV__
                /shared/la/la_probe.py --ckpt-dir=/shared/la/ckpt/$RUN --log-dir=$LA_OUT __ARGS__
